          Map<String, Object?> json) =>
      PutCorporateUserEmailPermissionsRequest(
        allFeaturesAccess: json.optBool('all_features_access') ??
            (throw BrevoDecodeException.missingRequiredKey(
                objectName: 'PutCorporateUserEmailPermissionsRequest',
                key: 'all_features_access')),
        privileges: json.containsKey('privileges')
